import{_ as a,o as e,c as d,a3 as r}from"./chunks/framework.BlfGB29P.js";const _=JSON.parse('{"title":"REST、GraphQL 与 RPC","description":"","frontmatter":{"title":"REST、GraphQL 与 RPC","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"frontend/decisions/data/api-style.md","filePath":"frontend/decisions/data/api-style.md","lastUpdated":1785589115000}'),h={name:"frontend/decisions/data/api-style.md"};function l(i,t,o,p,n,s){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="rest、graphql-与-rpc" tabindex="-1">REST、GraphQL 与 RPC <a class="header-anchor" href="#rest、graphql-与-rpc" aria-label="Permalink to &quot;REST、GraphQL 与 RPC&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>REST、GraphQL 与 RPC 解决的是不同接口组织问题。REST 围绕资源和 HTTP 语义，GraphQL 让客户端声明查询形状，RPC 围绕可调用过程和共享契约。它们都能被正确或错误地使用，也可以在不同边界共存。</p><h2 id="_1-决策背景" tabindex="-1">1. 决策背景 <a class="header-anchor" href="#_1-决策背景" aria-label="Permalink to &quot;1. 决策背景&quot;">​</a></h2><p>API 风格会影响缓存、错误模型、版本演进、客户端生成、网关、可观测性和组织所有权。只比较“请求次数”或“类型是否自动生成”会遗漏生产责任。</p><p>决策范围应明确是公开 API、内部 Web BFF、微服务通信还是单仓全栈应用。同一种风格不必覆盖所有边界。</p><h2 id="_2-硬约束与评价标准" tabindex="-1">2. 硬约束与评价标准 <a class="header-anchor" href="#_2-硬约束与评价标准" aria-label="Permalink to &quot;2. 硬约束与评价标准&quot;">​</a></h2><h3 id="_2-1-硬约束" tabindex="-1">2.1 硬约束 <a class="header-anchor" href="#_2-1-硬约束" aria-label="Permalink to &quot;2.1 硬约束&quot;">​</a></h3><ul><li>身份、授权和字段级数据暴露满足安全要求；</li><li>契约能够版本化、测试并在客户端与服务端独立发布时保持兼容；</li><li>网关、缓存、审计和可观测平台能够识别请求；</li><li>外部消费者能使用稳定、文档化且不过度绑定内部语言的协议；</li><li>批量、幂等、分页和错误语义覆盖关键业务。</li></ul><h3 id="_2-2-评价维度" tabindex="-1">2.2 评价维度 <a class="header-anchor" href="#_2-2-评价维度" aria-label="Permalink to &quot;2.2 评价维度&quot;">​</a></h3><p>比较消费者数量与差异、数据图复杂度、HTTP 缓存、类型共享、网关支持、查询成本控制、独立演进、调试、客户端生成和服务端治理。</p><h2 id="_3-候选方案" tabindex="-1">3. 候选方案 <a class="header-anchor" href="#_3-候选方案" aria-label="Permalink to &quot;3. 候选方案&quot;">​</a></h2><h3 id="_3-1-rest" tabindex="-1">3.1 REST <a class="header-anchor" href="#_3-1-rest" aria-label="Permalink to &quot;3.1 REST&quot;">​</a></h3><p>以资源 URL、HTTP 方法和状态码表达操作，便于利用通用网关、缓存和工具。适合公开接口、资源模型清楚和消费者独立演进的场景。页面需要跨多个资源时可能出现多请求或专用聚合端点。</p><h3 id="_3-2-graphql" tabindex="-1">3.2 GraphQL <a class="header-anchor" href="#_3-2-graphql" aria-label="Permalink to &quot;3.2 GraphQL&quot;">​</a></h3><p>通过 Schema 和查询语言让客户端选择字段，适合多种客户端访问关联数据且字段需求变化频繁。它需要字段授权、查询复杂度限制、N+1 治理、持久化查询、缓存和 Schema 演进能力。</p><h3 id="_3-3-rpc" tabindex="-1">3.3 RPC <a class="header-anchor" href="#_3-3-rpc" aria-label="Permalink to &quot;3.3 RPC&quot;">​</a></h3><p>以过程或方法为中心，常通过共享 Schema 生成客户端和服务端类型。适合同一组织、调用边界清楚、发布协调良好的内部系统。若直接暴露内部语言类型或把每个函数变成远程调用，会放大耦合。</p><h3 id="_3-4-组合边界" tabindex="-1">3.4 组合边界 <a class="header-anchor" href="#_3-4-组合边界" aria-label="Permalink to &quot;3.4 组合边界&quot;">​</a></h3><p>公开 API 可以使用 REST，Web 与 BFF 在受控单仓中使用类型化 RPC，复杂聚合产品使用 GraphQL。组合不是随意混用，应按消费者和治理边界指定默认风格。</p><h2 id="_4-关键维度对比" tabindex="-1">4. 关键维度对比 <a class="header-anchor" href="#_4-关键维度对比" aria-label="Permalink to &quot;4. 关键维度对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>REST</th><th>GraphQL</th><th>RPC</th></tr></thead><tbody><tr><td>公开互操作</td><td>强</td><td>强但需 GraphQL 客户端知识</td><td>取决于协议和生成器</td></tr><tr><td>HTTP 原生缓存</td><td>最自然</td><td>通常需额外策略</td><td>取决于传输</td></tr><tr><td>客户端选字段</td><td>有限</td><td>核心能力</td><td>通常由方法决定</td></tr><tr><td>类型端到端</td><td>可由 OpenAPI 生成</td><td>Schema 驱动</td><td>通常最直接</td></tr><tr><td>查询成本治理</td><td>端点级</td><td>字段和查询级，要求高</td><td>方法级</td></tr><tr><td>独立发布</td><td>成熟版本策略</td><td>Schema 兼容演进</td><td>易受共享类型耦合</td></tr><tr><td>调试与网关</td><td>通用工具成熟</td><td>需理解单端点查询</td><td>依实现</td></tr></tbody></table><h2 id="_5-场景化推荐结论" tabindex="-1">5. 场景化推荐结论 <a class="header-anchor" href="#_5-场景化推荐结论" aria-label="Permalink to &quot;5. 场景化推荐结论&quot;">​</a></h2><p>案例：物流平台需要向客户和合作伙伴开放订单、轨迹和费用接口；Web 门户由同一组织维护，但移动端和十余个外部集成独立发布。资源模型稳定，公共 CDN 需要缓存匿名轨迹。</p><p>推荐外部与领域 API 使用 REST，并以 OpenAPI 生成客户端和契约测试；Web 门户的页面聚合由 BFF 提供专用 REST 查询。暂不引入 GraphQL，因为客户端字段差异和数据图复杂度不足以覆盖 Schema 网关及成本治理投入。</p><p>内部单仓工具可在局部使用类型化 RPC，但不能把内部过程直接暴露给外部合作伙伴。</p><p>如果未来出现几十种客户端、关联查询快速增长且重复聚合端点失控，可试点 GraphQL；结论应由调用数据而非趋势驱动。</p><h2 id="_6-引入后的后果" tabindex="-1">6. 引入后的后果 <a class="header-anchor" href="#_6-引入后的后果" aria-label="Permalink to &quot;6. 引入后的后果&quot;">​</a></h2><p>REST 让缓存、网关和外部调试保持简单，同时接受部分页面需要聚合端点、字段可能过取和版本兼容工作。OpenAPI 只能生成结构类型，不能替代运行时验证、授权和业务语义。</p><p>无论选择哪种风格，都要定义错误、分页、幂等、取消、超时和弃用。接口风格不会自动解决这些问题。</p><p>退出成本来自消费者数量和契约绑定。外部 API 应以兼容演进为主，不能把“以后可迁移”建立在强迫所有消费者同步升级之上。</p><h2 id="_7-不适用场景" tabindex="-1">7. 不适用场景 <a class="header-anchor" href="#_7-不适用场景" aria-label="Permalink to &quot;7. 不适用场景&quot;">​</a></h2><ul><li>不要因一个页面请求多就立即引入 GraphQL，先确认 BFF 聚合或批量端点是否足够。</li><li>不要把 GraphQL 单端点误认为只能有一次网络请求。</li><li>不要把 TypeScript 类型当成运行时协议验证。</li><li>外部 API 不应暴露随内部函数重构变化的 RPC 方法。</li><li>REST 不要求机械地把每个动作都伪装成 CRUD；业务命令可使用清楚的子资源或动作契约。</li></ul><h2 id="_8-填写完成的决策记录" tabindex="-1">8. 填写完成的决策记录 <a class="header-anchor" href="#_8-填写完成的决策记录" aria-label="Permalink to &quot;8. 填写完成的决策记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>问题</td><td>物流平台对外和 Web 门户采用何种 API 风格</td></tr><tr><td>硬约束</td><td>外部独立消费者；匿名轨迹可缓存；网关审计；契约兼容</td></tr><tr><td>候选</td><td>REST、GraphQL、RPC、分边界组合</td></tr><tr><td>决定</td><td>对外和领域 REST；Web BFF 聚合；局部内部 RPC</td></tr><tr><td>证据</td><td>消费者访谈、调用图、缓存需求、三种原型的运维评估</td></tr><tr><td>接受代价</td><td>维护聚合端点和 OpenAPI；部分字段过取</td></tr><tr><td>明确不做</td><td>不建设组织级 GraphQL 网关；不向外暴露内部 RPC</td></tr><tr><td>成功指标</td><td>契约破坏数、聚合端点数、缓存命中、客户端升级周期、错误可定位率</td></tr></tbody></table><h2 id="_9-复查条件" tabindex="-1">9. 复查条件 <a class="header-anchor" href="#_9-复查条件" aria-label="Permalink to &quot;9. 复查条件&quot;">​</a></h2><p>客户端形态增长一个数量级、BFF 聚合端点连续高速增长、字段过取成为可测带宽瓶颈、GraphQL 治理能力已具备，或外部协议要求变化时复查。局部新需求不应触发全平台改写。</p>',37)])])}const b=a(h,[["render",l]]);export{_ as __pageData,b as default};
